#include <iostream>
#include <vector>
#include <algorithm>

int main() {
  std::vector<int> numbers = {1, 5, 2, 8, 3};
  // Using a const_iterator to find the maximum element without modifying the vector
  auto it = std::max_element(numbers.cbegin(), numbers.cend());
  if (it != numbers.cend()) {
    std::cout << "Maximum element: " << *it << std::endl;
  }
  // Demonstrating a common pitfall: Attempting modification via a const_iterator
  // *it = 10; // This will result in a compile-time error
  return 0;
}
